mapper.select:
SELECT p.id, p.plot_code AS plotCode, p.plot_name AS plotName, p.plot_type AS plotType, CASE p.plot_type WHEN 'field' THEN '大田' WHEN 'greenhouse' THEN '温室' WHEN 'orchard' THEN '果园' ELSE '其他' END AS plotTypeText, p.area, p.location_lat AS locationLat, p.location_lng AS locationLng, p.location_name AS locationName, p.crop_type AS cropType, p.crop_name AS cropName, p.status, CASE p.status WHEN 1 THEN '正常' ELSE '禁用' END AS statusText, p.create_by AS createBy, p.create_time AS createTime FROM agri_iot_plot p WHERE p.del_flag = 0
AND p.plot_code LIKE CONCAT('%', #{dto.plotCode}, '%')
AND p.plot_name LIKE CONCAT('%', #{dto.plotName}, '%')
AND p.plot_type = #{dto.plotType}
AND p.status = #{dto.status}
ORDER BY p.create_time DESC LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*) FROM agri_iot_plot p WHERE p.del_flag = 0
AND p.plot_code LIKE CONCAT('%', #{dto.plotCode}, '%')
AND p.plot_name LIKE CONCAT('%', #{dto.plotName}, '%')
AND p.plot_type = #{dto.plotType}
AND p.status = #{dto.status}
